import 'package:flutter/material.dart';\nimport 'package:flutter_test/flutter_test.dart';\nimport 'package:bdd_widget_test/bdd_widget_test.dart';\nimport 'package:fintracker/app.dart';\n\nvoid main() {\n  group('Sanitize Export Feature', () {\n    testWidgets('User can see sanitize export option', (tester) async {\n      await givenIAmOnTheSettingsScreen(tester);\n      await andIHaveSomePaymentDataInTheApp(tester);\n      await whenITapOnTheExportOption(tester);\n      await thenIShouldSeeExportFormatOptions(tester);\n      await andIShouldSeeASanitizeExportCheckbox(tester);\n      await andTheSanitizeOptionShouldBeUncheckedByDefault(tester);\n      await andIShouldSeeExplanatoryTextAboutRemovingPersonalInformation(tester);\n    });\n\n    testWidgets('User can export data without sanitization', (tester) async {\n      await givenIAmOnTheSettingsScreen(tester);\n      await andIHaveSomePaymentDataInTheApp(tester);\n      await whenITapOnTheExportOption(tester);\n      await andISelectAmountTypeFormat(tester);\n      await andILeaveTheSanitizeOptionUnchecked(tester);\n      await andIConfirmTheExport(tester);\n      await thenTheExportShouldProceedNormally(tester);\n    });\n\n    testWidgets('User can export data with sanitization enabled', (tester) async {\n      await givenIAmOnTheSettingsScreen(tester);\n      await andIHaveSomePaymentDataInTheApp(tester);\n      await whenITapOnTheExportOption(tester);\n      await andISelectDebitCreditFormat(tester);\n      await andICheckTheSanitizeExportOption(tester);\n      await andIConfirmTheExport(tester);\n      await thenIShouldSeeAConfirmationMessageMentioningPrivacyProtection(tester);\n    });\n\n    testWidgets('User can cancel export from options dialog', (tester) async {\n      await givenIAmOnTheSettingsScreen(tester);\n      await andIHaveSomePaymentDataInTheApp(tester);\n      await whenITapOnTheExportOption(tester);\n      await andITapTheCancelButtonInTheOptionsDialog(tester);\n      await thenTheExportDialogShouldClose(tester);\n      await andNoExportShouldBePerformed(tester);\n    });\n\n    testWidgets('Export confirmation shows different message for sanitized export', (tester) async {\n      await givenIAmOnTheSettingsScreen(tester);\n      await andIHaveSomePaymentDataInTheApp(tester);\n      await whenITapOnTheExportOption(tester);\n      await andICheckTheSanitizeExportOption(tester);\n      await andITapTheExportButton(tester);\n      await thenTheConfirmationDialogShouldMentionThatPersonalInformationWillBeRemoved(tester);\n    });\n\n    testWidgets('Export confirmation shows standard message for normal export', (tester) async {\n      await givenIAmOnTheSettingsScreen(tester);\n      await andIHaveSomePaymentDataInTheApp(tester);\n      await whenITapOnTheExportOption(tester);\n      await andILeaveTheSanitizeOptionUnchecked(tester);\n      await andITapTheExportButton(tester);\n      await thenTheConfirmationDialogShouldShowTheStandardExportMessage(tester);\n    });\n  });\n}\n\n// Step definitions\nFuture<void> givenIAmOnTheSettingsScreen(WidgetTester tester) async {\n  await tester.pumpWidget(const App());\n  await tester.pumpAndSettle();\n  \n  // Navigate to settings screen\n  // This would depend on your app's navigation structure\n  // For now, we'll assume we can find the settings screen directly\n}\n\nFuture<void> andIHaveSomePaymentDataInTheApp(WidgetTester tester) async {\n  // Mock some payment data in the app\n  // This would typically involve setting up test data in the database\n}\n\nFuture<void> whenITapOnTheExportOption(WidgetTester tester) async {\n  await tester.tap(find.byKey(const Key('settings_export_option')));\n  await tester.pumpAndSettle();\n}\n\nFuture<void> thenIShouldSeeExportFormatOptions(WidgetTester tester) async {\n  expect(find.text('Export Options'), findsOneWidget);\n  expect(find.text('Choose Export Format:'), findsOneWidget);\n  expect(find.text('Amount, Type'), findsOneWidget);\n  expect(find.text('Debit, Credit'), findsOneWidget);\n}\n\nFuture<void> andIShouldSeeASanitizeExportCheckbox(WidgetTester tester) async {\n  expect(find.byKey(const Key('sanitize_export_checkbox')), findsOneWidget);\n  expect(find.text('Sanitize Export'), findsOneWidget);\n}\n\nFuture<void> andTheSanitizeOptionShouldBeUncheckedByDefault(WidgetTester tester) async {\n  final checkbox = tester.widget<CheckboxListTile>(find.byKey(const Key('sanitize_export_checkbox')));\n  expect(checkbox.value, isFalse);\n}\n\nFuture<void> andIShouldSeeExplanatoryTextAboutRemovingPersonalInformation(WidgetTester tester) async {\n  expect(find.text('Remove personal information (names, account numbers, etc.)'), findsOneWidget);\n}\n\nFuture<void> andISelectAmountTypeFormat(WidgetTester tester) async {\n  await tester.tap(find.text('Amount, Type'));\n  await tester.pumpAndSettle();\n}\n\nFuture<void> andISelectDebitCreditFormat(WidgetTester tester) async {\n  await tester.tap(find.text('Debit, Credit'));\n  await tester.pumpAndSettle();\n}\n\nFuture<void> andILeaveTheSanitizeOptionUnchecked(WidgetTester tester) async {\n  // Option is unchecked by default, so no action needed\n}\n\nFuture<void> andICheckTheSanitizeExportOption(WidgetTester tester) async {\n  await tester.tap(find.byKey(const Key('sanitize_export_checkbox')));\n  await tester.pumpAndSettle();\n}\n\nFuture<void> andIConfirmTheExport(WidgetTester tester) async {\n  await tester.tap(find.text('Export'));\n  await tester.pumpAndSettle();\n  \n  // Confirm in the confirmation dialog\n  await tester.tap(find.text('Confirm'));\n  await tester.pumpAndSettle();\n}\n\nFuture<void> andITapTheExportButton(WidgetTester tester) async {\n  await tester.tap(find.text('Export'));\n  await tester.pumpAndSettle();\n}\n\nFuture<void> thenTheExportShouldProceedNormally(WidgetTester tester) async {\n  // Verify that export process starts (loading dialog appears)\n  expect(find.text('Exporting data, please wait...'), findsOneWidget);\n}\n\nFuture<void> thenIShouldSeeAConfirmationMessageMentioningPrivacyProtection(WidgetTester tester) async {\n  expect(find.textContaining('Personal information will be removed for privacy'), findsOneWidget);\n}\n\nFuture<void> andITapTheCancelButtonInTheOptionsDialog(WidgetTester tester) async {\n  await tester.tap(find.text('Cancel'));\n  await tester.pumpAndSettle();\n}\n\nFuture<void> thenTheExportDialogShouldClose(WidgetTester tester) async {\n  expect(find.text('Export Options'), findsNothing);\n}\n\nFuture<void> andNoExportShouldBePerformed(WidgetTester tester) async {\n  expect(find.text('Exporting data, please wait...'), findsNothing);\n}\n\nFuture<void> thenTheConfirmationDialogShouldMentionThatPersonalInformationWillBeRemoved(WidgetTester tester) async {\n  expect(find.textContaining('Personal information will be removed for privacy'), findsOneWidget);\n}\n\nFuture<void> thenTheConfirmationDialogShouldShowTheStandardExportMessage(WidgetTester tester) async {\n  expect(find.text('Want to export all the data to a file?'), findsOneWidget);\n  expect(find.textContaining('Personal information will be removed'), findsNothing);\n}